import{_ as a,c as t,o as s,ah as r,j as e,a as i}from"./chunks/framework.CAZQ2vdu.js";const o="/Qonnectra-docs/pr-17/images/manual/teil-a/microduct.jpg",d="/Qonnectra-docs/pr-17/images/manual/teil-a/microduct_drawer.jpg",h="/Qonnectra-docs/pr-17/images/manual/teil-a/microduct_table.jpg",l="/Qonnectra-docs/pr-17/images/manual/teil-a/microduct_highlight.jpg",c="/Qonnectra-docs/pr-17/videos/microduct_assign.webm",u="/Qonnectra-docs/pr-17/images/manual/teil-a/microduct_assign.jpg",w=JSON.parse('{"title":"13. Mikrorohre","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/13-mikrorohre.md","filePath":"manual/teil-a-anwenderhandbuch/13-mikrorohre.md"}'),m={name:"manual/teil-a-anwenderhandbuch/13-mikrorohre.md"};function k(b,n,p,g,f,_){return s(),t("div",null,[...n[0]||(n[0]=[r('<h1 id="_13-mikrorohre" tabindex="-1">13. Mikrorohre <a class="header-anchor" href="#_13-mikrorohre" aria-label="Permalink to &quot;13. Mikrorohre&quot;">​</a></h1><p>Die Ansicht <strong>Mikrorohre</strong> zeigt, welche Mikrorohre in den Rohren einer Trasse liegen und wofür sie belegt sind. Hier dokumentieren Sie außerdem, welcher Hausanschluss an welchem Mikrorohr hängt. Sie erreichen sie über die linke Navigationsleiste in der Gruppe „Rohr“ durch Klicken auf den Menüpunkt „Mikrorohre“.</p><p><img src="'+o+'" alt="Screenshot der Ansicht Mikrorohre mit der Karte des Projekts" data-zoomable="true"></p><p>Die Ansicht besteht aus einem Kartenfenster, das sich wie in Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a> beschrieben verhält, und der Info-Box, die sich mit dem ersten Klick öffnet.</p><h2 id="_13-1-graben-in-der-karte-auswahlen" tabindex="-1">13.1 Graben in der Karte auswählen <a class="header-anchor" href="#_13-1-graben-in-der-karte-auswahlen" aria-label="Permalink to &quot;13.1 Graben in der Karte auswählen&quot;">​</a></h2><p>Klicken Sie in der Karte auf ein Trassensegment. Anklickbar sind ausschließlich Trassen; Adressen, Netzknoten und Gebiete zeichnet die Karte nur zur Orientierung mit. Solange die Info-Box geschlossen ist, steht am unteren Rand der Karte der Hinweis „Klicken Sie auf einen Graben um die Sidebar zu öffnen.“</p><p>Mit dem Klick öffnet sich rechts die Info-Box mit der Trassen-ID als Überschrift. Sie hat hier nur den Reiter „Übersicht“ und darin die Rohre, die in der Trasse liegen – jedes in einer eigenen aufklappbaren Zeile mit Namen und Rohrtyp, etwa „St-V02-04 (12x10/6)“.</p><p><img src="'+d+'" alt="Screenshot der Ansicht Mikrorohre mit Hervorhebung der Info-Box am rechten Rand mit den Rohren der angeklickten Trasse" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Anwendung nennt das Trassensegment in dieser Ansicht „Graben“ und die Rohre „Leerrohre“. Gemeint sind dieselben Objekte wie in der Karte und in der Rohrverwaltung.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Liegt in der angeklickten Trasse kein Rohr, meldet die Info-Box „Keine Leerrohre in diesem Graben gefunden“. Welches Rohr in welcher Trasse liegt, legen Sie in der Rohrzuordnung fest, siehe Kapitel <a href="./11-rohrzuordnung.html">Rohrzuordnung</a>.</p></div><h2 id="_13-2-mikrorohrtabelle-nummer-farbe-status" tabindex="-1">13.2 Mikrorohrtabelle: Nummer, Farbe, Status <a class="header-anchor" href="#_13-2-mikrorohrtabelle-nummer-farbe-status" aria-label="Permalink to &quot;13.2 Mikrorohrtabelle: Nummer, Farbe, Status&quot;">​</a></h2><p>Klappen Sie ein Rohr auf, listet die Tabelle darunter seine Mikrorohre auf – mit denselben Spalten wie der Reiter „Status“ der Rohrverwaltung, siehe Abschnitt <a href="./10-rohrverwaltung.html#_10-4-mikrorohre-eines-rohrs">Mikrorohre eines Rohrs</a>: „#“, „Farbe“, „Adresse“, „Kabel“ und „Status“.</p><p><img src="'+h+'" alt="Screenshot der Ansicht Mikrorohre mit der Tabelle der Mikrorohre eines Rohrs in der verbreiterten Info-Box" data-zoomable="true"></p><p>Zwei Unterschiede zur Rohrverwaltung: Der Status ist hier nur zu lesen, und hinter jeder Zeile stehen die Schaltflächen zum Dokumentieren des Hausanschlusses, siehe Abschnitt <a href="#_13-4-hausanschlusse-dokumentieren">Hausanschlüsse dokumentieren</a>.</p><p>In der Standardbreite der Info-Box reicht die Tabelle über deren rechten Rand hinaus. Ziehen Sie die Info-Box breiter, bis die Schaltflächen sichtbar sind, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-6-die-info-box-mit-ihren-reitern">Die Info-Box</a>.</p><p>Sie können mehrere Rohre gleichzeitig aufgeklappt lassen; ein erneuter Klick auf die Zeile klappt eines wieder zu.</p><h2 id="_13-3-belegung-und-verbindungen" tabindex="-1">13.3 Belegung und Verbindungen <a class="header-anchor" href="#_13-3-belegung-und-verbindungen" aria-label="Permalink to &quot;13.3 Belegung und Verbindungen&quot;">​</a></h2><p>Womit ein Mikrorohr belegt ist, steht in zwei Spalten: „Adresse“ nennt den Hausanschluss, der daran hängt, „Kabel“ das eingezogene Kabel mit seinem Kabeltyp in Klammern. Bleiben beide leer, ist das Mikrorohr frei.</p><p>Die beiden Belegungen entstehen an verschiedenen Stellen: Den Hausanschluss tragen Sie hier ein, siehe Abschnitt <a href="#_13-4-hausanschlusse-dokumentieren">Hausanschlüsse dokumentieren</a>, das Kabel verknüpfen Sie im Netzschema, siehe Kapitel <a href="./14-netzschema.html">Netzschema</a>. Welche Mikrorohre an einem Rohrabzweig ineinander übergehen, zeigt diese Ansicht nicht; das steht in der Rohrverzweigung, siehe Kapitel <a href="./12-rohrverzweigung.html">Rohrverzweigung</a>.</p><p>Solange ein Rohr aufgeklappt ist, hebt die Karte alle Trassensegmente hervor, in denen dieses Rohr liegt – nicht nur das angeklickte. So sehen Sie, welchen Weg das Rohr im Netz nimmt, dessen Mikrorohre Sie gerade vor sich haben.</p><p><img src="'+l+'" alt="Screenshot der Ansicht Mikrorohre mit Hervorhebung des aufgeklappten Rohrs in der Info-Box und der farbig hervorgehobenen Trassensegmente in der Karte" data-zoomable="true"></p><p>Die Schaltfläche mit den Pfeilen in der Zeile eines Rohrs lädt dessen Mikrorohre neu aus der Datenbank. Sie hilft, wenn jemand anderes die Daten in der Zwischenzeit geändert hat.</p><h2 id="_13-4-hausanschlusse-dokumentieren" tabindex="-1">13.4 Hausanschlüsse dokumentieren <a class="header-anchor" href="#_13-4-hausanschlusse-dokumentieren" aria-label="Permalink to &quot;13.4 Hausanschlüsse dokumentieren&quot;">​</a></h2><p>Mit „Zuordnen“ verknüpfen Sie ein Mikrorohr mit einem Hausanschluss:</p><ol><li>Klicken Sie in der Zeile des Mikrorohrs auf „Zuordnen“.</li><li>Klicken Sie in der Karte auf den Netzknoten des Hausanschlusses.</li></ol>',25),e("p",null,[e("video",{src:c,controls:"",playsinline:"",preload:"metadata"},[i(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/microduct_assign.webm",download:""},"herunterladen"),i(" anstelle des Videos. ")])],-1),r('<p>Danach steht die Adresse des Netzknotens in der Spalte „Adresse“, und Qonnectra meldet „Hausanschluss erfolgreich zugeordnet“.</p><p>Zwischen den beiden Klicks befindet sich die Ansicht in einem eigenen Modus: In der Karte sind dann nur noch Netzknoten anklickbar, und alle Schaltflächen der Tabelle sind ausgegraut. Daran allein erkennen Sie den Modus – der Mauszeiger bleibt unverändert. Mit der Taste Esc brechen Sie ab, ohne etwas zu ändern.</p><p><img src="'+u+'" alt="Screenshot der Ansicht Mikrorohre mit Hervorhebung der Schaltflächen „Zuordnen“ und „Aufheben“ in der Tabelle der Mikrorohre" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Der angeklickte Netzknoten muss eine Adresse haben. Andernfalls meldet Qonnectra „Diesem Netzknoten wurde noch keine Adresse zugeordnet.“ und ändert nichts; der Modus bleibt aktiv, sodass Sie es gleich erneut versuchen können.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Trifft Ihr Klick gar keinen Netzknoten, schließt sich die Info-Box – der Modus bleibt trotzdem aktiv. Weil in ihm nur Netzknoten anklickbar sind, öffnet danach auch ein Klick auf eine Trasse keine Info-Box mehr, und die Ansicht wirkt, als reagiere sie nicht mehr. Drücken Sie Esc; erst danach können Sie wieder einen Graben auswählen.</p></div><p>„Aufheben“ löst die Verknüpfung wieder; die Schaltfläche steht nur in Zeilen, die eine Adresse haben. Qonnectra meldet „Hausanschluss erfolgreich aufgehoben“, und die Spalte „Adresse“ ist wieder leer.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Verknüpft wird das Mikrorohr mit dem Netzknoten, nicht mit der Adresse selbst; die Tabelle zeigt die Adresse dieses Netzknotens. Ein Netzknoten ohne Adresse kommt deshalb nicht infrage.</p></div>',7)])])}const z=a(m,[["render",k]]);export{w as __pageData,z as default};
